package dev.zomboidmelee.boxing;
import dev.zomboidmelee.boxing.CombatChecks18.*;import dev.zomboidmelee.boxing.Checks16.Stack;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.network.PacketDistributor;
public class InteractionsChecks22{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static class State{String id;State(String id){this.id=id;}public String getBlock(){return id;}}
 public static class World extends Level{public String id="minecraft:oak_door";public State getBlockState(Object pos){return new State(id);}}
 public static class P extends Actor{World w2=new World();public World level(){return w2;}}
 public static class Corpse{public String getType(){return "corpse:corpse";}}
 public static class Event{P p;public boolean canceled;public Object hand=net.minecraft.world.InteractionHand.MAIN_HAND;Event(P p){this.p=p;}public Object getEntity(){return p;}public Object getHand(){return hand;}public Object getPos(){return this;}public Object getTarget(){return new Corpse();}public boolean isCanceled(){return canceled;}}
 static int count(){return PacketDistributor.cues.size();}
 public static void main(String[]args){P p=new P();Event e=new Event(p);int n=count();Interact22.block(e);ok(count()==n+1&&((Heavy18)PacketDistributor.cues.getLast()).action()==22,"door interaction broadcasts a cosmetic reach");ok(!e.canceled,"never cancels the actual interaction");p.w2.id="minecraft:oak_trapdoor";Interact22.block(e);ok(count()==n+2,"trapdoor reach");p.w2.id="minecraft:barrel";Interact22.block(e);ok(count()==n+3,"barrel reach");p.w2.id="minecraft:stone";Interact22.block(e);ok(count()==n+3,"non-interactable stone excluded");p.w2.id="minecraft:oak_door";e.canceled=true;Interact22.block(e);ok(count()==n+3,"canceled interaction has no reach");e.canceled=false;p.main=new Stack(false);Interact22.block(e);ok(count()==n+3,"weapon/item animation remains in charge");p.main=new Stack(true);Interact22.entity(e);ok(count()==n+4,"corpse entity interaction reach");
 Minecraft mc=Minecraft.INSTANCE;mc.player=p;mc.level=p.w2;p.w2.entities.put(50,p);p.w2.client=true;long[]clock={2_000_000_000L};BoxingClient16.CLOCK=()->clock[0];Interact22.block(e);ok(count()==n+4&&Client20.kind(p)==Motion20.INTERACT,"client prediction never sends a clientbound packet");long start=Client20.state(p).start;Client20.receive(50,22);ok(Client20.state(p).start==start,"server confirmation does not restart reach");Net20.cue(p,22);ok(count()==n+4,"server-only broadcast rejects a client-side level too");clock[0]+=1_000_000_000L;Client20.begin(p,Motion20.STOMP,false);InteractClient22.show(p);ok(Client20.kind(p)==Motion20.STOMP,"interactions cannot replace a committed stomp");
 for(int kind:new int[]{Motion20.LIGHT,Motion20.HEAVY,Motion20.INTERACT})for(int i=0;i<=100;i++){var f=Motion20.arm(kind,0,0,i/100d);ok(Double.isFinite(f.x()+f.y()+f.z()+f.rx()+f.ry()+f.rz()),"finite tactical motion");}
 var jab=Motion20.arm(Motion20.LIGHT,0,0,.25);var guard=Motion20.arm(Motion20.LIGHT,0,0,1);ok(jab.z()<guard.z()-.55,"light strike extends decisively");var other=Motion20.arm(Motion20.LIGHT,1,0,.25);ok(other.y()<-.66&&other.z()>-.15,"opposite hand braces instead of mimicking punch");var reach=Motion20.arm(Motion20.INTERACT,0,0,.39);ok(reach.z()<-.60&&reach.rz()>20,"interaction has its own reach and wrist movement");ok(p.x==5&&p.y==7&&p.z==9,"camera/arms never move player root");Client20.state(p).start=0;Client20.begin(p,Motion20.LIGHT,true);clock[0]+=100_000_000L;Client20.state(p).contact=clock[0]-40_000_000L;Camera lightCamera=new Camera();Client20.camera(lightCamera);ok(lightCamera.pitch-10>.4&&Math.abs(lightCamera.pitch-10)<6,"light camera has stronger bounded confirmed shake");clock[0]+=1_000_000_000L;Client20.begin(p,Motion20.HEAVY,true);clock[0]+=276_000_000L;Client20.state(p).contact=clock[0]-40_000_000L;Camera heavyCamera=new Camera();Client20.camera(heavyCamera);ok(heavyCamera.pitch-10>lightCamera.pitch-10&&Math.abs(heavyCamera.pitch-10)<6,"heavy shake stronger than light without changing player view rotation");clock[0]+=1_000_000_000L;Client20.begin(p,Motion20.INTERACT,true);clock[0]+=100_000_000L;Camera doorCamera=new Camera();Client20.camera(doorCamera);ok(doorCamera.pitch==10&&doorCamera.roll==2,"opening a door does not cause combat impact shake");System.out.println("TACTICAL_JAB_BRACE_INTERACTION_PREDICTION_SERVER_SAFETY_CHECKS="+checks);}
}
